  };

  if (error?.message?.includes('timeout')) {
    context.possibleCauses.push('API timeout or slow response');
    context.suggestedActions.push('Check external service status');
  }
  if (error?.message?.includes('auth')) {
    context.possibleCauses.push('Authentication/authorization issue');
    context.suggestedActions.push('Verify API credentials');
  }

  return context;
};

