export const code = async (inputs) => {
  const blocks = inputs.blocks?.results || [];

  const extractRichText = (richText) => {
    if (!Array.isArray(richText)) return '';
    return richText.map(t => t.plain_text || '').join('');
  };

  const textBlocks = blocks.filter(b => {
    const t = b.type;
    return ['paragraph', 'heading_1', 'heading_2', 'heading_3', 
            'bulleted_list_item', 'numbered_list_item', 'quote', 
            'callout', 'toggle', 'to_do'].includes(t);
  });

  const concatenatedText = textBlocks.map(b => {
    const content = b[b.type];
    return extractRichText(content?.rich_text || content?.text);
  }).filter(t => t).join('\n\n');

  return {
    documentId: inputs.pageId,
    title: inputs.title,
    content: concatenatedText,
    metadata: {
      source: 'notion',
      createdAt: new Date().toISOString(),
      blockCount: textBlocks.length,
      charCount: concatenatedText.length
    }
  };
};

export const code = async (inputs) => {
  const blocks = inputs.blocks?.results || [];
  const textBlockTypes = ['paragraph', 'heading_1', 'heading_2', 'heading_3', 'bulleted_list_item', 'numbered_list_item', 'quote'];

  const textParts = blocks
    .filter(b => textBlockTypes.includes(b.type))
    .map(b => {
      const content = b[b.type];
      const richText = content?.rich_text || [];
      return richText.map(t => t.plain_text).join('');
    })
    .filter(t => t.length > 0);

  const fullText = textParts.join(' ');
  const words = fullText.split(/\s+/);

  // Create concise summary (first 100 words + key points)
  const summary = words.length > 100 
    ? words.slice(0, 100).join(' ') + '...' 
    : fullText;

  return {
    pageTitle: inputs.title,
    summary: summary,
    totalWords: words.length,
    textBlocks: textParts.length
  };
};

