export const code = async (inputs) => {
  const url = inputs.youtubeUrl || '';
  let videoId = '';

  // Extract video ID from various YouTube URL formats
  const patterns = [
    /(?:youtube\.com\/watch\?v=)([^&]+)/,
    /(?:youtu\.be\/)([^?]+)/,
    /(?:youtube\.com\/embed\/)([^?]+)/
  ];

  for (const pattern of patterns) {
    const match = url.match(pattern);
    if (match) {
      videoId = match[1];
      break;
    }
  }

  return {
    videoId: videoId,
    originalUrl: url,
    isValid: videoId.length > 0
  };
};

