    headingCount: data.headings?.length || 0,
    h1Count: data.headings?.filter(h => h.level === 1).length || 0,
    ctaCount: data.cta_buttons?.length || 0,
    imageCount: data.images?.length || 0,
    imagesWithAlt: data.images?.filter(i => i.alt).length || 0,
    linkCount: data.links?.length || 0,
    internalLinks: data.links?.filter(l => l.internal).length || 0,
    externalLinks: data.links?.filter(l => !l.internal).length || 0
  };

  // CRO Score calculation
  let score = 0;
  if (analysis.title !== 'Missing') score += 10;
  if (analysis.metaDescription !== 'Missing') score += 10;
  if (analysis.h1Count === 1) score += 15;
  if (analysis.ctaCount > 0) score += 20;
  if (analysis.imagesWithAlt === analysis.imageCount && analysis.imageCount > 0) score += 15;

  analysis.croScore = score;
  analysis.maxScore = 70;

  return analysis;
};

