export const code = async (inputs) => {
  const response = (inputs.response || '').toLowerCase().trim();
  const validSentiments = ['positive', 'negative', 'neutral'];
  const sentiment = validSentiments.find(s => response.includes(s));
  return { sentiment: sentiment || null, hasSentiment: !!sentiment };
};
